"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["96275"],{92646(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>m,frontMatter:()=>d,contentTitle:()=>p,toc:()=>h,assets:()=>c});var n=JSON.parse('{"id":"hiecm/v3/api/m1/endpoints/m1-enrolment-by-aadhaar","title":"Create an ABHA from a verified Aadhaar OTP","description":"Exchanges the OTP you just received for a real ABHA number. Send the","source":"@site/docs/hiecm/v3/api/m1/endpoints/m1-enrolment-by-aadhaar.mdx","sourceDirName":"hiecm/v3/api/m1/endpoints","slug":"/hiecm/v3/api/m1/endpoints/m1-enrolment-by-aadhaar","permalink":"/docs/pr-10/docs/hiecm/v3/api/m1/endpoints/m1-enrolment-by-aadhaar","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1789327770000,"frontMatter":{"title":"Create an ABHA from a verified Aadhaar OTP","sidebar_label":"Create an ABHA from a verified Aadhaar OTP","sidebar_class_name":"api-method api-method--post","description":"Exchanges the OTP you just received for a real ABHA number. Send the","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"hiecm-m1.yaml","generated":true},"sidebar":"hiecm-v3-api","previous":{"title":"Send an OTP to begin or continue an enrolment","permalink":"/docs/pr-10/docs/hiecm/v3/api/m1/endpoints/m1-enrolment-request-otp"},"next":{"title":"Verify an OTP that ABDM sent, during enrolment","permalink":"/docs/pr-10/docs/hiecm/v3/api/m1/endpoints/m1-enrolment-verify-abdm-otp"}}'),r=a(62540),i=a(43023),s=a(70862),o=JSON.parse('{"id":"m1_enrolment_by_aadhaar","module":"M1 ABHA identity","moduleId":"m1","kind":"operation","method":"POST","path":"/v3/enrollment/enrol/byAadhaar","server":"https://abhasbx.abdm.gov.in/abha/api","servers":[{"url":"https://abhasbx.abdm.gov.in/abha/api","description":"ABHA Server, Sandbox (primary)"},{"url":"https://dev.abdm.gov.in/api/hiecm","description":"ABDM Gateway, Dev"}],"summary":"Create an ABHA from a verified Aadhaar OTP","description":"Exchanges the OTP you just received for a real ABHA number. Send the\\n`txnId` from the OTP request, the encrypted OTP value, and the consent\\nblock recording that the person agreed.\\n\\nThis is the call that creates the account, so treat a success as a\\npermanent side effect. If you retry it blindly after a timeout you may be\\nenrolling somebody twice.\\n\\n`BENEFIT_NAME` is sent on this call when the enrolment belongs to a\\nbenefit scheme.\\n\\nThe demographic authentication variant reads the user token from a\\ndifferent place: `token` at the top level, while the OTP, face and\\nfingerprint variants take `tokens.token`. Check which one you get\\nbefore parsing.\\n","security":[{"name":"gatewaySession","type":"http","scheme":"bearer","description":"The `accessToken` from `POST /api/hiecm/gateway/v3/sessions`, which is described in hiecm-gateway.yaml. Send it as `Authorization: Bearer <ACCESS_TOKEN>`.\\n"},{"name":"bearerAuth","type":"http","scheme":"bearer","description":"JWT Bearer token from `POST /api/hiecm/gateway/v3/sessions`.\\nHeader: `Authorization: Bearer {accessToken}`\\n"},{"name":"xToken","type":"apiKey","description":"Short-lived session token returned in login/verify responses.\\nRequired for all `/profile/account/*` operations.\\nHeader: `X-Token: {token}`\\n"}],"headers":[{"name":"REQUEST-ID","required":true,"description":"Unique UUID v4 per request. Used for idempotency and distributed tracing.\\nGenerate a fresh UUID for every call.\\n","type":"string"},{"name":"TIMESTAMP","required":true,"description":"ISO 8601 UTC timestamp of the request.","type":"string"},{"name":"BENEFIT_NAME","required":false,"description":"The benefit scheme an enrolment belongs to. On enrolment and benefit calls, the value is `healthid api` on the enrol and search calls, and `healthid` on the login OTP and verify calls under Find ABHA and on some of the benefit calls. On the enrolment OTP request the header is present but explicitly disabled, so it is not sent there.\\n\\nThis header is spelled four different ways across requests: `BENEFIT_NAME` (most), `Benefit-Name` (demo auth and child ABHA calls), `BENEFIT-NAME` (child update, state district search) and `Benefit_Name` (once). Underscore and hyphen are different header names on the wire. Benefit programme calls also use scheme values beyond healthid: `COVIN` on an IRIS enrol and a profile photo update, and a disabled `PAN`.\\n\\nWhich spelling is correct has not been confirmed against the sandbox.\\n","example":"healthid api","type":"string"},{"name":"X-token","required":false,"description":"The user scoped token returned when a person logs in or verifies an OTP. Profile calls act on one account, so they need this in addition to the gateway token. Required on the calls that read or change a specific person\'s account.\\n\\nThe value carries a `Bearer ` prefix, exactly like the Authorization header. Sending the bare token reads as an invalid token error.\\n","example":"Bearer <X_TOKEN_FROM_LOGIN_VERIFY>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"authData","type":"object","required":true,"description":"","encrypted":false},{"name":"authData.authMethods","type":"string[]","required":true,"description":"","encrypted":false},{"name":"authData.otp","type":"object","required":false,"description":"","encrypted":false},{"name":"authData.otp.txnId","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.otp.otpValue","type":"string","required":false,"description":"","encrypted":true},{"name":"authData.otp.mobile","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.otp.fingerPrintAuthPid","type":"string","required":false,"description":"","encrypted":false},{"name":"authData.otp.timeStamp","type":"string","required":false,"description":"","encrypted":false},{"name":"authData.face","type":"object","required":false,"description":"","encrypted":false},{"name":"authData.face.txnId","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.face.aadhaar","type":"string","required":true,"description":"","encrypted":true},{"name":"authData.iris","type":"object","required":false,"description":"","encrypted":false},{"name":"authData.iris.aadhaar","type":"string","required":true,"description":"","encrypted":true},{"name":"authData.iris.Pid","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.iris.mobile","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.bio","type":"object","required":false,"description":"","encrypted":false},{"name":"authData.bio.aadhaar","type":"string","required":true,"description":"","encrypted":true},{"name":"authData.bio.fingerPrintAuthPid","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.bio.mobile","type":"string","required":true,"description":"","encrypted":false},{"name":"consent","type":"object","required":true,"description":"","encrypted":false},{"name":"consent.code","type":"string","required":true,"description":"","encrypted":false},{"name":"consent.version","type":"string","required":true,"description":"","encrypted":false}],"requestExample":{"authData":{"authMethods":["otp"],"otp":{"txnId":"<TXN_ID>","otpValue":"<OTPVALUE>","mobile":"<MOBILE>"}},"consent":{"code":"abha-enrollment","version":"1.4"}},"responses":[{"status":"200","description":"Response body: not documented."},{"status":"400","description":"Bad Request, invalid scope, loginHint, or encrypted field","example":{"scope":"Invalid Scope","timestamp":"2024-05-10 11:13:04"}},{"status":"401","description":"Unauthorized, missing, invalid, or expired Bearer token","example":{"code":"<CODE>","message":"<MESSAGE>","timestamp":"<TIMESTAMP>"}},{"status":"403","description":"Forbidden, the token is valid but not permitted for this operation","example":{"code":"<CODE>","message":"<MESSAGE>","timestamp":"<TIMESTAMP>"}},{"status":"422","description":"Unprocessable, the request parsed but failed validation","example":{"code":"<CODE>","message":"<MESSAGE>","timestamp":"<TIMESTAMP>"}},{"status":"500","description":"Server error, retry","example":{"code":"<CODE>","message":"<MESSAGE>","timestamp":"<TIMESTAMP>"}}],"tag":"ABHA creation, Aadhaar OTP","tagDescription":"","curl":"curl --request POST \\\\\\n  --url https://abhasbx.abdm.gov.in/abha/api/v3/enrollment/enrol/byAadhaar \\\\\\n  --header \'REQUEST-ID: <REQUEST_ID>\' \\\\\\n  --header \'TIMESTAMP: <TIMESTAMP>\' \\\\\\n  --header \'BENEFIT_NAME: healthid api\' \\\\\\n  --header \'X-token: Bearer <X_TOKEN_FROM_LOGIN_VERIFY>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"authData\\": {\\n    \\"authMethods\\": [\\n      \\"otp\\"\\n    ],\\n    \\"otp\\": {\\n      \\"txnId\\": \\"<TXN_ID>\\",\\n      \\"otpValue\\": \\"<OTPVALUE>\\",\\n      \\"mobile\\": \\"<MOBILE>\\"\\n    }\\n  },\\n  \\"consent\\": {\\n    \\"code\\": \\"abha-enrollment\\",\\n    \\"version\\": \\"1.4\\"\\n  }\\n}\'"}');let d={title:"Create an ABHA from a verified Aadhaar OTP",sidebar_label:"Create an ABHA from a verified Aadhaar OTP",sidebar_class_name:"api-method api-method--post",description:"Exchanges the OTP you just received for a real ABHA number. Send the",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"hiecm-m1.yaml",generated:!0},p,c={},h=[];function l(e){return(0,r.jsx)(s.A,{operation:o})}function m(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}}}]);